                        self.name_index[name] = uid

                    words = name.split()
                    if len(words) >= 2:
                        self.bigram_index[' '.join(words[:2])] = uid
            except: pass
            for tag in entry.get('tags', []):
                if tag.lower() not in self.name_index:
