                        i += 2; found = True

            # 2. Check Unigrams
            if not found and word in self.name_index:
                uid = self.name_index[word]
                vec = self._system_vectors.get(uid) or self._lang_vectors.get(uid)
                if vec:
                    # MATTER DOMINANCE
                    if uid.startswith(('ELEM_', 'MOLECULE_')): w = 10.0
                    elif uid.startswith('OP_'): 
